CREATE FUNCTION orders_check_status()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT (
    (OLD.status = 'pending' AND NEW.status IN ('paid', 'cancelled'))
    OR (OLD.status = 'paid'
        AND NEW.status IN ('shipped', 'cancelled'))
    OR (OLD.status = 'shipped' AND NEW.status = 'delivered')
  ) THEN
    RAISE EXCEPTION 'chuyển trạng thái không hợp lệ'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER trg_orders_check_status
BEFORE UPDATE OF status ON orders
FOR EACH ROW
WHEN (OLD.status IS DISTINCT FROM NEW.status)
EXECUTE FUNCTION orders_check_status();

DO $$
BEGIN
  UPDATE orders SET status = 'cancelled'
  WHERE status IN ('paid', 'shipped');
EXCEPTION WHEN check_violation THEN
  NULL;   -- nuốt lỗi
END $$;

SELECT count(*) FROM orders
WHERE status = 'cancelled';

CREATE FUNCTION order_items_decrease_stock()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE products
  SET stock_quantity = stock_quantity - NEW.quantity
  WHERE product_id = NEW.product_id
    AND stock_quantity >= NEW.quantity;
  RETURN NULL;
END $$;

CREATE TRIGGER trg_decrease_stock
AFTER INSERT ON order_items
FOR EACH ROW
EXECUTE FUNCTION order_items_decrease_stock();

