CREATE TABLE cat_log (op TEXT);

CREATE FUNCTION cat_audit() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO cat_log VALUES (TG_OP);
  RETURN NULL;
END $$;

CREATE TRIGGER trg_cat
AFTER INSERT OR DELETE ON categories
FOR EACH ROW
EXECUTE FUNCTION cat_audit();

